--
-- Name: generate_allotment_letter_dml_trig(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_allotment_letter_dml_trig() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
    DECLARE
	list integer;
    BEGIN
	DELETE FROM housing_virtual_roaster_counter
	WHERE roaster_counter = NEW.roaster_counter
	AND list_no = NEW.list_no
	AND flat_type = NEW.flat_type;

	UPDATE housing_virtual_roaster_counter SET list_no = list_no - 1 
	WHERE flat_type = NEW.flat_type 
	AND NOT EXISTS (SELECT 1 FROM housing_virtual_roaster_counter WHERE list_no = 1 
			AND flat_type = NEW.flat_type
			) ;

	UPDATE housing_allotment_letter 
	SET list_no = (
				SELECT COALESCE(MAX(list_no),0) AS list_no 
				FROM housing_allotment_letter 
				WHERE roaster_counter = NEW.roaster_counter 
				AND flat_type = NEW.flat_type
				AND allotment_letter_id != NEW.allotment_letter_id
			) + 1 
	WHERE allotment_letter_id = NEW.allotment_letter_id;
	

        RETURN NULL; 
    END;
$$;


ALTER FUNCTION public.generate_allotment_letter_dml_trig() OWNER TO postgres;

