--

CREATE FUNCTION public.housing_flat_status_update_log() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
	IF NEW.flat_status_id <> OLD.flat_status_id THEN
		 VALUES(OLD.flat_id,OLD.flat_status_id,NEW.flat_status_id,now());
	END IF;
	RETURN NEW;
END;
$$;


ALTER FUNCTION public.housing_flat_status_update_log() OWNER TO postgres;

--
-- Name: next_roaster_counter(character, integer, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.next_roaster_counter(ft character, list integer, cat character varying) RETURNS TABLE(counter integer, list_no integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
   c_counter    integer;
   temp_counter integer;
   max_category integer;
BEGIN
	IF (list = 1) THEN
		-- fetch last proposed roaster counter respective to the flat type -> into temp_counter
		SELECT COALESCE(MAX(hal.roaster_counter),0) AS rc INTO temp_counter FROM housing_allotment_letter hal 
		WHERE hal.list_no = (SELECT COALESCE(MAX(hl.list_no),0) AS l FROM housing_allotment_letter hl WHERE hl.flat_type = ft)
		AND hal.flat_type = ft;
		
		-- if proposed counter reaches at the end, set to initial -> into temp_counter
		IF (temp_counter = 29) THEN
			temp_counter = 0;
		END IF;

		-- if no proposal found yet, respective to the flat type
		IF (temp_counter = 0) THEN
		
		-- then fetch last allotted roaster counter respective to the flat type -> into temp_counter
			SELECT hrc.counter INTO temp_counter
			FROM
			housing_roaster_counter hrc
			INNER JOIN housing_flat_type hft
			ON hft.flat_type_id = hrc.flat_type_id
			WHERE
			hft.flat_type = ft;

			-- if allotted counter reaches at the end, set to initial -> into temp_counter
			IF (temp_counter = 29) THEN
				temp_counter = 0;
			END IF;
		END IF;
	ELSE
		temp_counter = 0;
	END IF;
        -- fetching next roaster counter from AB master table
	IF(ft = 'A' OR ft = 'B') THEN 
	-- count no of rows having the said category in AB master table
	SELECT COALESCE(MAX(hrabm.counter),0) INTO max_category FROM housing_roaster4ab_master hrabm 
	WHERE hrabm.category = cat;
	-- if it's only 1, set to initial -> into temp_counter
	IF(max_category <= temp_counter) THEN
		temp_counter = 0;
	END IF;

           SELECT hrabm.counter INTO c_counter
           FROM
           housing_roaster4ab_master hrabm
           WHERE
           hrabm.counter NOT IN
          (
		SELECT hvrc.roaster_counter
		FROM
		housing_virtual_roaster_counter hvrc
		WHERE
		hvrc.flat_type = ft
		AND hvrc.list_no = list
		AND hvrc.category = cat
           )
           AND hrabm.counter > temp_counter
           AND hrabm.category = cat
           LIMIT 1;	
	-- if no counter found go for next list i.e next recursion call
           IF(c_counter IS NULL) THEN
            list = list + 1;
            RETURN QUERY
            SELECT * FROM next_roaster_counter(ft,list,cat);
	-- if legal counter found return as the desired result
           ELSE
            RETURN QUERY
            SELECT c_counter as counter, list as list_no;
           END IF;
      
      -- fetching next roaster counter from CD master table
        ELSE
	-- count no of rows having the said category in CD master table
	SELECT COALESCE(MAX(hrcdm.counter),0) INTO max_category FROM housing_roaster4cd_master hrcdm 
	WHERE hrcdm.category = cat;
	-- if it's only 1, set to initial -> into temp_counter
	IF(max_category <= temp_counter) THEN
		temp_counter = 0;
	END IF;

           SELECT hrcdm.counter INTO c_counter  
           FROM
           housing_roaster4cd_master hrcdm
           WHERE hrcdm.counter NOT IN
          (
		SELECT hvrc.roaster_counter
		FROM
		housing_virtual_roaster_counter hvrc
		WHERE
		hvrc.flat_type = ft
		AND hvrc.list_no = list
		AND hvrc.category = cat
           )
           AND hrcdm.counter > temp_counter
           AND hrcdm.category = cat
           LIMIT 1;
	-- if no counter found go for next list i.e next recursion call
           IF(c_counter IS NULL) THEN
            list = list + 1;
            RETURN QUERY
            SELECT * FROM next_roaster_counter(ft,list,cat);
           ELSE
	-- if legal counter found return as the desired result
            RETURN QUERY
            SELECT c_counter as counter, list as list_no;
           END IF;
        END IF;
 
    


END
$$;


ALTER FUNCTION public.next_roaster_counter(ft character, list integer, cat character varying) OWNER TO postgres;

--
-- Name: process_online_application_no(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.process_online_application_no() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
    BEGIN 
	
UPDATE housing_online_application SET application_no = (SELECT upper(NEW.application_no)|| '-' || to_char(current_timestamp, 'DDMMYYYY')|| '-' || uid FROM(
SELECT (
SELECT hoa.online_application_id FROM housing_applicant ha INNER JOIN housing_applicant_official_detail haod ON ha.housing_applicant_id = haod.housing_applicant_id 
INNER JOIN housing_online_application hoa ON hoa.applicant_official_detail_id = haod.applicant_official_detail_id WHERE haod.is_active = 1
and hoa.online_application_id = NEW.online_application_id ) AS uid) t) where online_application_id = NEW.online_application_id ;

        RETURN NULL;
    END;
$$;


ALTER FUNCTION public.process_online_application_no() OWNER TO postgres;

--
-- Name: process_roaster_counter_29(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.process_roaster_counter_29() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
    BEGIN 
	DELETE FROM housing_virtual_roaster_counter WHERE list_no = 1 AND roaster_counter = NEW.counter AND flat_type = (SELECT flat_type FROM housing_flat_type WHERE flat_type_id = NEW.flat_type_id) ;
        UPDATE housing_virtual_roaster_counter SET list_no = list_no - 1 WHERE flat_type = (SELECT flat_type FROM housing_flat_type WHERE flat_type_id = NEW.flat_type_id) AND NOT EXISTS (SELECT 1 FROM housing_virtual_roaster_counter WHERE list_no = 1 AND flat_type = (SELECT flat_type FROM housing_flat_type WHERE flat_type_id = NEW.flat_type_id)) ;
  
        RETURN NULL;
    END;
$$;


ALTER FUNCTION public.process_roaster_counter_29() OWNER TO postgres;

--
-- Name: process_update_housing_allotment_letter(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.process_update_housing_allotment_letter() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
    BEGIN 
	UPDATE housing_allotment_letter SET list_no = list_no - 1 WHERE flat_type = OLD.flat_type AND NOT EXISTS (SELECT 1 FROM housing_allotment_letter WHERE list_no = 1 AND flat_type = OLD.flat_type) ;
        RETURN NULL;
    END;
$$;


ALTER FUNCTION public.process_update_housing_allotment_letter() OWNER TO postgres;

--
-- Name: process_update_list(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.process_update_list() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
    BEGIN 
	IF(NEW.online_application_id IS NOT NULL)THEN
	
		UPDATE housing_roaster_counter SET counter = (SELECT roaster_counter FROM housing_allotment_letter WHERE online_application_id = NEW.online_application_id)
		WHERE flat_type_id = (SELECT flat_type_id FROM housing_flat WHERE flat_id = NEW.flat_id);

		UPDATE housing_online_application SET status = 'allotted' WHERE online_application_id = NEW.online_application_id;

		DELETE FROM housing_allotment_letter WHERE online_application_id = NEW.online_application_id;
	
	END IF;
	UPDATE housing_flat SET flat_status_id = (SELECT flat_status_id FROM housing_flat_status WHERE is_occupied = TRUE) WHERE flat_id = NEW.flat_id ;
        RETURN NULL;
    END;
$$;


ALTER FUNCTION public.process_update_list() OWNER TO postgres;

--
-- Name: process_update_roaster_counter(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.process_update_roaster_counter() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
    DECLARE
        id bigint;
    a_allotment_category character varying(60);
    f_flat_type character(1);
    c_counter integer;
    l_list_no integer;
    BEGIN
    id = NEW.online_application_id;     
    SELECT flat_type INTO f_flat_type FROM housing_application_data WHERE online_application_id = id;
    SELECT allotment_category INTO a_allotment_category FROM housing_application_data WHERE online_application_id = id;
    IF(NEW.status = 'verified' AND OLD.status != 'verified' AND f_flat_type IS NOT NULL AND a_allotment_category IS NOT NULL)THEN
        SELECT counter INTO c_counter FROM next_roaster_counter(f_flat_type,1, a_allotment_category);
        SELECT list_no INTO l_list_no FROM next_roaster_counter(f_flat_type,1, a_allotment_category);
 
    END IF;
 
        RETURN NULL;
    END;
$$;


ALTER FUNCTION public.process_update_roaster_counter() OWNER TO postgres;

