--
-- Name: housing_application_data; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.housing_application_data AS
 SELECT 'New Allotment Application'::text AS application_type,
    hoa.online_application_id,
    hoa.date_of_application,
    ha.applicant_name,
    haod.grade_pay,
    hna.allotment_category,
    hna.flat_type_id,
    hft.flat_type
   FROM ((((public.housing_online_application hoa
     JOIN public.housing_new_allotment_application hna ON ((hoa.online_application_id = hna.online_application_id)))
     JOIN public.housing_flat_type hft ON ((hna.flat_type_id = hft.flat_type_id)))
     JOIN public.housing_applicant_official_detail haod ON ((hoa.applicant_official_detail_id = haod.applicant_official_detail_id)))
     JOIN public.housing_applicant ha ON ((ha.uid = haod.uid)))
  WHERE (((hoa.status)::text = 'verified'::text) AND (NOT (hoa.online_application_id IN ( SELECT housing_allotment_letter.online_application_id
           FROM public.housing_allotment_letter))))
UNION
 SELECT 'Vertical Shifting Application'::text AS application_type,
    hoa.online_application_id,
    hoa.date_of_application,
    ha.applicant_name,
    haod.grade_pay,
    hva.allotment_category,
    hva.flat_type_id,
    hft.flat_type
   FROM ((((public.housing_online_application hoa
     JOIN public.housing_vs_application hva ON ((hoa.online_application_id = hva.online_application_id)))
     JOIN public.housing_flat_type hft ON ((hva.flat_type_id = hft.flat_type_id)))
     JOIN public.housing_applicant_official_detail haod ON ((hoa.applicant_official_detail_id = haod.applicant_official_detail_id)))
     JOIN public.housing_applicant ha ON ((ha.uid = haod.uid)))
  WHERE (((hoa.status)::text = 'verified'::text) AND (NOT (hoa.online_application_id IN ( SELECT housing_allotment_letter.online_application_id
           FROM public.housing_allotment_letter))))
UNION
 SELECT 'Category Shifting Application'::text AS application_type,
    hoa.online_application_id,
    hoa.date_of_application,
    ha.applicant_name,
    haod.grade_pay,
    hca.allotment_category,
    hca.flat_type_id,
    hft.flat_type
   FROM ((((public.housing_online_application hoa
     JOIN public.housing_cs_application hca ON ((hoa.online_application_id = hca.online_application_id)))
     JOIN public.housing_flat_type hft ON ((hca.flat_type_id = hft.flat_type_id)))
     JOIN public.housing_applicant_official_detail haod ON ((hoa.applicant_official_detail_id = haod.applicant_official_detail_id)))
     JOIN public.housing_applicant ha ON ((ha.uid = haod.uid)))
  WHERE (((hoa.status)::text = 'verified'::text) AND (NOT (hoa.online_application_id IN ( SELECT housing_allotment_letter.online_application_id
           FROM public.housing_allotment_letter))))
  ORDER BY 2;


ALTER TABLE public.housing_application_data OWNER TO postgres;

